60: 	struct Node
61: 	{
62: 		using Counter = unsigned int;
63: 
64: 		Node(const Callback_ & callback, const Counter counter)
65: 			: callback(callback), counter(counter)
66: 		{
67: 		}
68: 
69: 		NodePtr previous;
70: 		NodePtr next;
71: 		Callback_ callback;
72: 		Counter counter;
73: 	};
