75: 	class Handle_ : public std::weak_ptr<Node>
76: 	{
77: 	private:
78: 		using super = std::weak_ptr<Node>;
79: 
80: 	public:
81: 		using super::super;
82: 
83: 		operator bool () const noexcept {
84: 			return ! this->expired();
85: 		}
86: 	};
