93: public:
94: 	using Callback = Callback_;
95: 	using Handle = Handle_;
96: 	using Mutex = typename Threading::Mutex;
97: 
98: public:
99: 	CallbackListBase() noexcept
100: 		:
101: 			head(),
102: 			tail(),
103: 			mutex(),
104: 			currentCounter(0)
105: 	{
106: 	}
107: 
108: 	CallbackListBase(const CallbackListBase & other)
109: 		: CallbackListBase()
110: 	{
111: 		cloneFrom(other.head);
112: 	}
113: 
114: 	CallbackListBase(CallbackListBase && other) noexcept
115: 		: CallbackListBase()
116: 	{
117: 		swap(other);
118: 	}
