120: 	// If we use pass by value idiom and omit the 'this' check,
121: 	// when assigning to self there is a deep copy which is inefficient.
122: 	CallbackListBase & operator = (const CallbackListBase & other) {
123: 		if(this != &other) {
124: 			CallbackListBase copied(other);
125: 			swap(copied);
126: 		}
127: 		return *this;
128: 	}
129: 
130: 	CallbackListBase & operator = (CallbackListBase && other) noexcept {
131: 		if(this != &other) {
132: 			doFreeAllNodes();
133: 
134: 			head = std::move(other.head);
135: 			tail = std::move(other.tail);
136: 			currentCounter = other.currentCounter.load();
137: 		}
138: 		return *this;
139: 	}
140: 
141: 	~CallbackListBase()	{
142: 		// Don't lock mutex here since it may throw exception
143: 
144: 		doFreeAllNodes();
145: 	}
146: 	
147: 	void swap(CallbackListBase & other) noexcept {
148: 		using std::swap;
149: 		
150: 		swap(head, other.head);
151: 		swap(tail, other.tail);
152: 
153: 		const auto value = currentCounter.load();
154: 		currentCounter.exchange(other.currentCounter.load());
155: 		other.currentCounter.exchange(value);
156: 	}
