158: 	bool empty() const {
159: 		// Don't lock the mutex for performance reason.
160: 		// !head still works even when the underlying raw pointer is garbled (for other thread is writting to head)
161: 		// And empty() doesn't guarantee the list is still empty after the function returned.
162: 		//std::lock_guard<Mutex> lockGuard(mutex);
163: 
164: 		return ! head;
165: 	}
166: 
167: 	operator bool() const {
168: 		return ! empty();
169: 	}
