171: 	Handle append(const Callback & callback)
172: 	{
173: 		NodePtr node(doAllocateNode(callback));
174: 
175: 		std::lock_guard<Mutex> lockGuard(mutex);
176: 
177: 		if(head) {
178: 			node->previous = tail;
179: 			tail->next = node;
180: 			tail = node;
181: 		}
182: 		else {
183: 			head = node;
184: 			tail = node;
185: 		}
186: 
187: 		return Handle(node);
188: 	}
