190: 	Handle prepend(const Callback & callback)
191: 	{
192: 		NodePtr node(doAllocateNode(callback));
193: 
194: 		std::lock_guard<Mutex> lockGuard(mutex);
195: 
196: 		if(head) {
197: 			node->next = head;
198: 			head->previous = node;
199: 			head = node;
200: 		}
201: 		else {
202: 			head = node;
203: 			tail = node;
204: 		}
205: 
206: 		return Handle(node);
207: 	}
