210: 	{
211: 		// Disable this assertion because it's too slow in debug mode.
212: 		//assert(before.expired() || ownsHandle(before));
213: 
214: 		NodePtr beforeNode = before.lock();
215: 		if(beforeNode) {
216: 			NodePtr node(doAllocateNode(callback));
217: 
218: 			std::lock_guard<Mutex> lockGuard(mutex);
219: 
220: 			doInsert(node, beforeNode);
221: 
222: 			return Handle(node);
223: 		}
224: 
225: 		return append(callback);
226: 	}
