228: 	bool remove(const Handle & handle)
229: 	{
230: 		// Disable this assertion because it's too slow in debug mode.
231: 		//assert(handle.expired() || ownsHandle(handle));
232: 
233: 		// It looks like the lock can be put inside the `if` below,
234: 		// but that doesn't work in multi-threading and cause related unit tests fail.
235: 		std::lock_guard<Mutex> lockGuard(mutex);
236: 
237: 		auto node = handle.lock();
238: 		if(node) {
239: 			doFreeNode(node);
240: 			return true;
241: 		}
242: 
243: 		return false;
244: 	}
