246: 	bool ownsHandle(const Handle & handle) const
247: 	{
248: 		std::lock_guard<Mutex> lockGuard(mutex);
249: 
250: 		auto node = handle.lock();
251: 		if(node) {
252: 			while(node->previous) {
253: 				node = node->previous;
254: 			}
255: 			return node == head;
256: 		}
257: 
258: 		return false;
259: 	}
