261: 	template <typename Func>
262: 	void forEach(Func && func) const
263: 	{
264: 		doForEachIf([&func, this](NodePtr & node) -> bool {
265: 			doForEachInvoke<void>(func, node);
266: 			return true;
267: 		});
268: 	}
