270: 	template <typename Func>
271: 	bool forEachIf(Func && func) const
272: 	{
273: 		return doForEachIf([&func, this](NodePtr & node) -> bool {
274: 			return doForEachInvoke<bool>(func, node);
275: 		});
276: 	}
