278: #if !defined(__GNUC__) || __GNUC__ >= 5
279: 	void operator() (Args ...args) const
280: 	{
281: 		forEachIf([&args...](Callback & callback) -> bool {
282: 			// We can't use std::forward here, because if we use std::forward,
283: 			// for arg that is passed by value, and the callback prototype accepts it by value,
284: 			// std::forward will move it and may cause the original value invalid.
285: 			// That happens on any value-to-value passing, no matter the callback moves it or not.
286: 
287: 			callback(args...);
288: 			return CanContinueInvoking::canContinueInvoking(args...);
289: 		});
290: 	}
291: #else
292: 	// This is a patch version for GCC 4. It inlines the unrolled doForEachIf.
293: 	// GCC 4.8.3 doesn't supporting parameter pack catpure in lambda, see,
294: 	// https://github.com/wqking/eventpp/issues/19
295: 	// This is a compromised patch for GCC 4, it may be not maintained or updated unless there are bugs.
296: 	// We don't use the patch as main code because the patch generates longer code, and duplicated with doForEachIf.
297: 	void operator() (Args ...args) const
298: 	{
299: 		NodePtr node;
300: 
301: 		{
302: 			std::lock_guard<Mutex> lockGuard(mutex);
303: 			node = head;
304: 		}
305: 
306: 		const Counter counter = currentCounter.load(std::memory_order_acquire);
307: 
308: 		while(node) {
309: 			if(node->counter != removedCounter && counter >= node->counter) {
310: 				node->callback(args...);
311: 				if(! CanContinueInvoking::canContinueInvoking(args...)) {
312: 					break;
313: 				}
314: 			}
315: 
316: 			{
317: 				std::lock_guard<Mutex> lockGuard(mutex);
318: 				node = node->next;
319: 			}
320: 		}
321: 	}
322: #endif
