324: private:
325: 	template <typename F>
326: 	bool doForEachIf(F && f) const
327: 	{
328: 		NodePtr node;
329: 
330: 		{
331: 			std::lock_guard<Mutex> lockGuard(mutex);
332: 			node = head;
333: 		}
334: 
335: 		const Counter counter = currentCounter.load(std::memory_order_acquire);
336: 
337: 		while(node) {
338: 			if(node->counter != removedCounter && counter >= node->counter) {
339: 				if(! f(node)) {
340: 					return false;
341: 				}
342: 			}
343: 
344: 			{
345: 				std::lock_guard<Mutex> lockGuard(mutex);
346: 				node = node->next;
347: 			}
348: 		}
349: 
350: 		return true;
351: 	}
