353: 	template <typename RT, typename Func>
354: 	auto doForEachInvoke(Func && func, NodePtr & node) const
355: 		-> typename std::enable_if<CanInvoke<Func, Handle, Callback &>::value, RT>::type
356: 	{
357: 		return func(Handle(node), node->callback);
358: 	}
