367: 	void doInsert(NodePtr & node, NodePtr & beforeNode)
368: 	{
369: 		node->previous = beforeNode->previous;
370: 		node->next = beforeNode;
371: 		if(beforeNode->previous) {
372: 			beforeNode->previous->next = node;
373: 		}
374: 		beforeNode->previous = node;
375: 
376: 		if(beforeNode == head) {
377: 			head = node;
378: 		}
379: 	}
380: 	
381: 	NodePtr doAllocateNode(const Callback & callback)
382: 	{
383: 		return std::make_shared<Node>(callback, getNextCounter());
384: 	}
385: 	
386: 	void doFreeNode(NodePtr & node)
387: 	{
388: 		if(node->next) {
389: 			node->next->previous = node->previous;
390: 		}
391: 		if(node->previous) {
392: 			node->previous->next = node->next;
393: 		}
394: 
395: 		// Mark it as deleted, this must be before the assignment of head and tail below,
396: 		// because node can be a reference to head or tail, and after the assignment, node
397: 		// can be null pointer.
398: 		node->counter = removedCounter;
399: 
400: 		if(head == node) {
401: 			head = node->next;
402: 		}
403: 		if(tail == node) {
404: 			tail = node->previous;
405: 		}
406: 
407: 		// don't modify node->previous or node->next
408: 		// because node may be still used in a loop.
409: 	}
410: 
411: 	void doFreeAllNodes() {
412: 		NodePtr node = head;
413: 		head.reset();
414: 		while(node) {
415: 			NodePtr next = node->next;
416: 			node->previous.reset();
417: 			node->next.reset();
418: 			node = next;
419: 		}
420: 		node.reset();
421: 	}
422: 
423: 	Counter getNextCounter()
424: 	{
425: 		Counter result = ++currentCounter;;
426: 		if(result == 0) { // overflow, let's reset all nodes' counters.
427: 			{
428: 				std::lock_guard<Mutex> lockGuard(mutex);
429: 				NodePtr node = head;
430: 				while(node) {
431: 					node->counter = 1;
432: 					node = node->next;
433: 				}
434: 			}
435: 			result = ++currentCounter;
436: 		}
437: 
438: 		return result;
439: 	}
440: 	
441: 	void cloneFrom(const NodePtr & fromHead) {
442: 		NodePtr fromNode(fromHead);
443: 		NodePtr node;
444: 		const Counter counter = getNextCounter();
445: 		while(fromNode) {
446: 			const NodePtr nextNode(std::make_shared<Node>(fromNode->callback, counter));
447: 
448: 			nextNode->previous = node;
449: 
450: 			if(node) {
451: 				node->next = nextNode;
452: 			}
453: 			else {
454: 				node = nextNode;
455: 				head = node;
456: 			}
457: 		
458: 			node = nextNode;
459: 			fromNode = fromNode->next;
460: 		}
461: 
462: 		tail = node;
463: 	}
464: 
