58: 	template <typename T>
59: 	class HomoCallbackListType : public CallbackList<T, UnderlyingPoliciesType_>, public HomoCallbackListTypeBase
60: 	{
61: 	private:
62: 		using super = CallbackList<T, UnderlyingPoliciesType_>;
63: 
64: 	public:
65: 		virtual bool empty() override {
66: 			return super::empty();
67: 		}
68: 
69: 		virtual bool doRemove(const HeterHandle_ & handle) override {
70: 			auto sp = handle.homoHandle.lock();
71: 			if(! sp) {
72: 				return false;
73: 			}
74: 			return this->remove(typename super::Handle(std::static_pointer_cast<typename super::Handle::element_type>(sp)));
75: 		}
