118: 	// If we use pass by value idiom and omit the 'this' check,
119: 	// when assigning to self there is a deep copy which is inefficient.
120: 	HeterCallbackListBase & operator = (const HeterCallbackListBase & other) noexcept
121: 	{
122: 		if(this != &other) {
