124: 			swap(copied);
125: 		}
126: 		return *this;
127: 	}
128: 
129: 	HeterCallbackListBase & operator = (HeterCallbackListBase && other) noexcept
130: 	{
131: 		if(this != &other) {
132: 			for(size_t i = 0; i < callbackListList.size(); ++i) {
133: 				callbackListList[i] = std::move(other.callbackListList[i]);
134: 			}
135: 		}
136: 
137: 		return *this;
138: 	}
