160: 	template <typename C>
161: 	Handle append(const C & callback)
162: 	{
163: 		using PrototypeInfo = FindPrototypeByCallable<PrototypeList_, C>;
164: 		static_assert(PrototypeInfo::index >= 0, "Can't find invoker for the given argument types.");
165: 
166: 		auto callbackList= doGetCallbackList<PrototypeInfo>();
167: 		return Handle {
168: 			PrototypeInfo::index,
169: 			callbackList->append(callback)
