174: 	Handle prepend(const C & callback)
175: 	{
176: 		using PrototypeInfo = FindPrototypeByCallable<PrototypeList_, C>;
177: 		static_assert(PrototypeInfo::index >= 0, "Can't find invoker for the given argument types.");
178: 
179: 		auto callbackList= doGetCallbackList<PrototypeInfo>();
180: 		return Handle {
181: 			PrototypeInfo::index,
182: 			callbackList->prepend(callback)
183: 		};
184: 	}
