186: 	template <typename C>
187: 	Handle insert(const C & callback, const Handle & before)
188: 	{
189: 		using PrototypeInfo = FindPrototypeByCallable<PrototypeList_, C>;
190: 		static_assert(PrototypeInfo::index >= 0, "Can't find invoker for the given argument types.");
191: 
192: 		auto callbackList= doGetCallbackList<PrototypeInfo>();
193: 
194: 		if(before.index != PrototypeInfo::index) {
195: 			return Handle {
196: 				PrototypeInfo::index,
197: 				callbackList->append(callback)
198: 			};
199: 		}
200: 
201: 		using UnderlyingHandle = typename decltype(callbackList)::element_type::Handle;
202: 
203: 		return Handle {
204: 			PrototypeInfo::index,
205: 			callbackList->insert(
206: 				callback,
207: 				UnderlyingHandle(std::static_pointer_cast<typename UnderlyingHandle::element_type>(before.homoHandle.lock()))
208: 			)
209: 		};
210: 	}
