212: 	bool remove(const Handle & handle)
213: 	{
214: 		auto callbackList = callbackListList[handle.index];
215: 		if(callbackList) {
216: 			return callbackList->doRemove(handle);
217: 		}
218: 
219: 		return false;
220: 	}
