222: 	template <typename Prototype, typename Func>
223: 	void forEach(Func && func) const
224: 	{
225: 		using PrototypeInfo = FindPrototypeByCallable<PrototypeList, Prototype>;
226: 		static_assert(PrototypeInfo::index >= 0, "Can't find invoker for the given argument types.");
227: 
228: 		auto callbackList= doGetCallbackList<PrototypeInfo>();
229: 		using CL = typename decltype(callbackList)::element_type;
230: 		callbackList->forEach([this, &func](const typename CL::Handle & handle, const typename CL::Callback & callback) {
231: 			doForEachInvoke<void, PrototypeInfo::index>(func, handle, callback);
232: 		});
233: 	}
