236: 	bool forEachIf(Func && func) const
237: 	{
238: 		using PrototypeInfo = FindPrototypeByCallable<PrototypeList, Prototype>;
239: 		static_assert(PrototypeInfo::index >= 0, "Can't find invoker for the given argument types.");
240: 
241: 		auto callbackList= doGetCallbackList<PrototypeInfo>();
242: 		using CL = typename decltype(callbackList)::element_type;
243: 		return callbackList->forEachIf([this, &func](const typename CL::Handle & handle, const typename CL::Callback & callback) {
244: 			return doForEachInvoke<bool, PrototypeInfo::index>(func, handle, callback);
245: 		});
