26: template <typename Item, typename Handle, typename Mutex>
27: bool removeHandleFromScopedRemoverItemList(std::vector<Item> & itemList, Handle & handle, Mutex & mutex)
28: {
29: 	if(! handle) {
30: 		return false;
31: 	}
32: 	auto handlePointer = handle.lock();
33: 	std::unique_lock<Mutex> lock(mutex);
34: 	auto it = std::find_if(itemList.begin(), itemList.end(), [&handlePointer](Item & item) {
35: 		return item.handle && item.handle.lock() == handlePointer;
36: 	});
37: 	if(it != itemList.end()) {
38: 		itemList.erase(it);
39: 		return true;
40: 	}
41: 	return false;
42: }
