80: 	{
81: 		dispatcher = std::move(other.dispatcher);
82: 		itemList = std::move(other.itemList);
83: 		other.reset();
84: 		return *this;
85: 	}
86: 	
87: 	~ScopedRemover()
88: 	{
89: 		reset();
90: 	}
91: 	
92: 	void swap(ScopedRemover & other) noexcept {
93: 		using std::swap;
94: 
95: 		swap(dispatcher, other.dispatcher);
96: 		swap(itemList, other.itemList);
97: 	}
98: 
99: 	void reset()
100: 	{
101: 		if(dispatcher != nullptr) {
102: 			for(const auto & item : itemList) {
103: 				dispatcher->removeListener(item.event, item.handle);
104: 			}
